import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Solution {
    public int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) graph.add(new ArrayList<>());
        for (int[] pair : prerequisites) graph.get(pair[1]).add(pair[0]);
        int[] state = new int[numCourses];
        List<Integer> postorder = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) {
            if (state[course] == 0 && !visit(course, graph, state, postorder)) return new int[0];
        }
        Collections.reverse(postorder);
        int[] order = new int[numCourses];
        for (int index = 0; index < numCourses; index++) order[index] = postorder.get(index);
        return order;
    }
    private boolean visit(int course, List<List<Integer>> graph, int[] state, List<Integer> postorder) {
        if (state[course] == 1) return false;
        if (state[course] == 2) return true;
        state[course] = 1;
        for (int next : graph.get(course)) if (!visit(next, graph, state, postorder)) return false;
        state[course] = 2;
        postorder.add(course);
        return true;
    }
}

