import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

class Solution {
    public int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        int[] indegree = new int[numCourses];
        for (int course = 0; course < numCourses; course++) graph.add(new ArrayList<>());
        for (int[] pair : prerequisites) { graph.get(pair[1]).add(pair[0]); indegree[pair[0]]++; }
        Queue<Integer> ready = new ArrayDeque<>();
        for (int course = 0; course < numCourses; course++) if (indegree[course] == 0) ready.offer(course);
        int[] order = new int[numCourses];
        int size = 0;
        while (!ready.isEmpty()) {
            int course = ready.poll();
            order[size++] = course;
            for (int next : graph.get(course)) if (--indegree[next] == 0) ready.offer(next);
        }
        return size == numCourses ? order : new int[0];
    }
}
